import {resultCard,referenceResults} from './code-results.js';
import {fetchData} from './data-fetch.js';
import {documents,coverage,loadArchive,findDocuments} from './archive-store.js';
import {documentTitle} from './plain-language.js';
import {exportDocuments} from './personal-docs.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let deps={},kind='rap',query='',repo='전체',fileType='전체',workflows=null;
const sections=[['3e6a6b8522df81998314f08175fdd7de','전체 객체·개발 순서','Table부터 서비스·Behavior까지'],['3e6a6b8522df81eb8227f772adc128d6','데이터·CDS·값도움','조회·Text View·검색'],['3e6a6b8522df817c9539cb0d26b5d00d','BO·Behavior','CRUD·EML·Action·검증'],['3e6a6b8522df812dad2ec270b76f8346','Fiori·서비스','Metadata·OData·Draft'],['3e6a6b8522df81ca8c2bc6980b3be47d','전체 프로젝트','구매·입고·회계 실제 코드'],['3e6a6b8522df81499cdac11b61fa544b','수업 원본·캡처','날짜별 실습 기록']];
export function hubPage(){kind=location.hash.startsWith('#github')?'github':'rap';query='';repo='전체';fileType='전체';return `<section class="hub-page"><header class="archive-heading"><div class="archive-kicker">${kind==='rap'?'RAP / BUILD IN ORDER':'GITHUB / MY SOURCE'}</div><h1>${kind==='rap'?'RAP, 객체 순서대로 구현하기':'내 GitHub 프로젝트 찾기'}</h1><p>${kind==='rap'?'내 노션의 구조와 작업 순서를 따라 설명·구현·전체 프로젝트를 연결했습니다.':'ABAP-STUDY와 masterpack FI의 프로그램·Include·화면·DDIC·UI5 원본을 함께 찾습니다.'}</p></header><div class="archive-search"><span aria-hidden="true">⌕</span><input id="hub-search" type="search" aria-label="${kind==='rap'?'RAP':'GitHub'} 기능·본문·코드 검색" placeholder="${kind==='rap'?'예: 값도움, VALIDATION, MODIFY ENTITIES, Draft…':'예: 전표, f4_belnr, ZE3QM0001, Controller, UI5…'}" autocomplete="off"></div><div id="hub-content"><p>자료를 불러오는 중…</p></div></section>`;}
const row=d=>`<button class="hub-document" data-hub-doc="${esc(d.id)}"><span>${esc(d.source==='GitHub'?(d.repo||'ABAP-STUDY'):d.track||d.category)} · ${d.components?'프로그램 묶음':d.recipe?'전체 코드':'원문'}</span><strong>${esc(documentTitle(d))}</strong>${d.source==='GitHub'?`<code class="hub-source-path">${esc(d.path)}</code>`:''}<small>${esc(d.task?.intent||d.summary)}</small><em>열어서 읽기 ↗</em></button>`;
function draw(){const target=document.querySelector('#hub-content');if(!target)return;
 if(kind==='rap'){
 const allMatches=findDocuments(query).filter(d=>d.track==='RAP'),matches=query?allMatches.filter(d=>d.codeInfo.hasCode):allMatches;
 target.innerHTML=query?`<div class="hub-result-heading"><strong>RAP ${matches.length}개 결과</strong><span>제목·본문·코드 전체 검색</span></div><div class="hub-documents">${matches.slice(0,20).map(d=>resultCard(d,query)).join('')||'<p>검색 결과가 없습니다.</p>'}</div>${matches.length>20?'<p>상위 20개 표시 · 기능명을 더 입력해 좁힐 수 있습니다.</p>':''}${referenceResults(allMatches)}`:
 `<div class="rap-sections">${sections.map(([id,title,sub],i)=>`<button data-hub-doc="notion-${id}"><span>0${i}</span><strong>${title}</strong><small>${sub}</small></button>`).join('')}</div><div class="hub-section-heading"><h2>지금 할 일에서 시작하세요</h2><p>각 단계에서 작업할 객체와 완료 기준을 확인하고 원문 코드로 이동합니다.</p></div><div class="rap-workflows">${(workflows?.rap||[]).map(w=>`<article><span class="workflow-step">STEP ${String(w.order).padStart(2,'0')}</span><h3>${esc(w.task)}</h3><p class="workflow-location">${esc(w.location)}</p><details class="workflow-details"><summary>개발 순서 · 완료 기준</summary><ol>${w.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="workflow-check"><strong>완료 확인</strong><p>${esc(w.check)}</p></div></details><div class="workflow-actions"><button data-hub-doc="notion-${w.id}">설명·구현 코드 열기 →</button>${w.projectReferenceId&&w.id!==w.projectReferenceId?`<button data-hub-doc="notion-${w.projectReferenceId}">전체 프로젝트 연결</button>`:''}</div></article>`).join('')}</div><p class="hub-footnote">노션 RAP 하위 ${matches.length}개 문서 · 원문과 프로젝트별 전제조건을 함께 확인하세요.</p>`;
 }else{
 const allMatches=findDocuments(query,{source:'GitHub'});
 let matches=allMatches.filter(d=>repo==='전체'||(d.repo||'ABAP-STUDY')===repo);
 if(fileType!=='전체')matches=matches.filter(d=>fileType==='프로그램 묶음'?d.components:fileType==='UI5'?/\.(js|xml|json|css|properties|yaml)$/i.test(d.path):fileType==='DDIC'?d.category==='DDIC':fileType==='화면'?/화면|GUI/.test(d.role||''):!d.components);
 if(fileType==='전체')matches=matches.filter(d=>d.codeInfo.hasCode);
 const fi=coverage.masterpackInventory?.fileCount||0;
 target.innerHTML=`<div class="repo-cards">${[['ABAP-STUDY','ALV·이벤트·화면·ABAP 기초',coverage.githubInventory?.fileCount||966],['masterpack-project-fi','전표·F4·엑셀·FI/QM·UI5',fi]].map(([name,desc,count])=>`<button class="${repo===name?'active':''}" data-hub-repo="${name}"><span>GITHUB REPOSITORY</span><strong>${name}</strong><small>${desc}</small><em>원본 파일 ${count}개</em></button>`).join('')}</div><div class="hub-filter-row"><label>저장소<select id="hub-repo"><option>전체</option>${['ABAP-STUDY','masterpack-project-fi'].map(r=>`<option ${repo===r?'selected':''}>${r}</option>`).join('')}</select></label><label>자료 종류<select id="hub-type">${['전체','프로그램 묶음','원본 파일','UI5','DDIC','화면'].map(t=>`<option ${fileType===t?'selected':''}>${t}</option>`).join('')}</select></label><span>${matches.length}개 결과 · ${fileType==='전체'?'코드 있는 자료만':'선택한 파일 유형'}</span></div><div class="hub-documents">${matches.slice(0,20).map(d=>resultCard(d,query)).join('')||'<p>검색 결과가 없습니다.</p>'}</div>${matches.length>20?'<p class="hub-footnote">상위 20개 표시 · 기능명·파일명 검색으로 좁혀주세요.</p>':''}${referenceResults(allMatches.filter(d=>repo==='전체'||(d.repo||'ABAP-STUDY')===repo))}`;
 }
}
export async function renderHub(){try{await loadArchive();if(!workflows){workflows=await fetchData('./workflows.json');}draw();}catch(e){const el=document.querySelector('#hub-content');if(el)el.textContent=e.message;}}
export function savedDocumentsPanel(){return `<section class="saved-documents"><div class="hub-section-heading"><h2>저장한 원문과 최근 자료</h2><p>노션·GitHub 문서의 ‘자료 저장’ 버튼으로 다시 쓸 자료를 모으세요.</p></div><div id="saved-documents-content"></div></section>`;}
export async function renderSavedDocuments(){await loadArchive();const target=document.querySelector('#saved-documents-content');if(!target)return;const data=exportDocuments();target.innerHTML=['saved','recent'].map(k=>{const list=data[k].map(id=>documents.find(d=>d.id===id)).filter(Boolean);return `<h3>${k==='saved'?'저장한 자료':'최근 읽은 자료'}</h3><div class="saved-document-list">${list.slice(0,k==='saved'?30:8).map(row).join('')||'<p>아직 자료가 없습니다.</p>'}</div>`;}).join('');}
export function bindHub(d){deps=d;document.addEventListener('input',e=>{if(e.target.id==='hub-search'){query=e.target.value;draw();}});document.addEventListener('change',e=>{if(e.target.id==='hub-repo'){repo=e.target.value;draw();}if(e.target.id==='hub-type'){fileType=e.target.value;draw();}});document.addEventListener('click',e=>{const b=e.target.closest('[data-hub-doc],[data-hub-repo]');if(!b)return;if(b.dataset.hubDoc)deps.navigate('docs',b.dataset.hubDoc);if(b.dataset.hubRepo){repo=repo===b.dataset.hubRepo?'전체':b.dataset.hubRepo;draw();}});}
